function processOrder(order):
    chargeCustomer(order)
    reserveInventory(order)

    if currentTime() < 5:00 PM:
        requestSameDayPickup(order)
    else:
        requestNextDayPickup(order)

    waitUntilDelivered(order)
    sendReviewEmail(order)
